} from "../../src/node/apiUtils.mjs";
import excludedOperations from "../../src/node/config/excludedOperations.mjs";

describe("node API utilities", () => {
    test("sanitise normalises operation names and search terms", () => {
        expect(sanitise("To Base-64 / value.2")).toBe("tobase64value2");
        expect(sanitise("TO\tBASE\n64")).toBe("tobase64");
        expect(sanitise("alreadyClean")).toBe("alreadyclean");
    });

    test("decapitalise changes only a normal leading capital", () => {
        expect(decapitalise("SomeName")).toBe("someName");
        expect(decapitalise("Base64")).toBe("base64");
        expect(decapitalise("X")).toBe("x");
        expect(decapitalise("ABCValue")).toBe("ABCValue");
        expect(decapitalise("Return")).toBe("Return");
    });

    test("sentenceToCamelCase joins words while preserving acronyms", () => {
        expect(sentenceToCamelCase("something like this")).toBe("somethingLikeThis");
        expect(sentenceToCamelCase("To Base64")).toBe("toBase64");
        expect(sentenceToCamelCase("ABC a sentence")).toBe("ABCASentence");
        expect(sentenceToCamelCase("one")).toBe("one");
    });

    test("removeSubheadingsFromArray removes only complete heading entries", () => {
        const input = ["[Group]", "[Multi\nLine]", "A", 7, "[partial", "not [heading]"];
        const result = removeSubheadingsFromArray(input);

        expect(result).toEqual(["A", 7, "[partial", "not [heading]"]);
        expect(input).toHaveLength(6);
        expect(removeSubheadingsFromArray([])).toEqual([]);
    });

    test("node-only exclusions contain flow control and unavailable operations", () => {
        expect(excludedOperations).toEqual([
            "Fork",
            "Merge",
            "Jump",
            "ConditionalJump",
            "Label",
            "Comment",
            "JavaScriptBeautify",
            "JavaScriptMinify",
            "JavaScriptParser",
            "SyntaxHighlighter",
        ]);
        expect(new Set(excludedOperations).size).toBe(excludedOperations.length);
    });
});
EOF

cat > test/node/File.test.mjs <<'EOF'
import File from "../../src/node/File.mjs";

describe("node File shim", () => {
    test("concatenates chunks and exposes file metadata", () => {
        const encoder = new TextEncoder();
        const file = new File(
            [new File("abc"), Buffer.from("def"), encoder.encode("ghi").buffer],
            "combined.bin",
            {lastModified: 123456},
        );

        expect(file.data).toEqual(Buffer.from("abcdefghi"));
        expect(file.size).toBe(9);
        expect(file.name).toBe("combined.bin");
        expect(file.lastModified).toBe(123456);
        expect(file.lastModifiedDate).toEqual(new Date(123456));
        expect(file.type).toBe("application/unknown");
    });

    test("detects the MIME type from magic bytes", () => {
        const pngHeader = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
        const file = new File(pngHeader, "tiny.png", {lastModified: 42});

        expect(file.type).toBe("image/png");
        expect(file.size).toBe(pngHeader.length);
        expect(file.data).toEqual(pngHeader);
    });

    test("uses empty/default metadata for omitted constructor options", () => {
        const before = Date.now();
        const file = new File("hello");
        const after = Date.now();

        expect(file.name).toBe("");
        expect(file.size).toBe(5);
        expect(file.data.toString()).toBe("hello");
        expect(file.type).toBe("application/unknown");
        expect(file.lastModified).toBeGreaterThanOrEqual(before);
        expect(file.lastModified).toBeLessThanOrEqual(after);
        expect(file.lastModifiedDate).toEqual(new Date(file.lastModified));
    });

    test("an empty chunk list creates an empty file", () => {
        const file = new File([]);

        expect(file.size).toBe(0);
        expect(file.data).toEqual(Buffer.alloc(0));
        expect(file.type).toBe("application/unknown");
    });
});
EOF

cat > test/node/NodeDish.test.mjs <<'EOF'
import util from "node:util";

// Import the aggregate API first: it establishes the normal ESM dependency
// order used by the node module before the lower-level files are inspected.
import chef from "../../src/node/index.mjs";
import Dish from "../../src/core/Dish.mjs";
import NodeDish from "../../src/node/NodeDish.mjs";

describe("NodeDish", () => {
    test("treats an fs Buffer as a byte-array dish", () => {
        const dish = new NodeDish(Buffer.from("hello"));

        expect(dish).toBeInstanceOf(Dish);
        expect(dish.type).toBe(Dish.BYTE_ARRAY);
        expect(dish.value).toEqual([104, 101, 108, 108, 111]);
        expect(dish.get("string")).toBe("hello");
    });

    test("supports primitive coercion without producing a primitive dish", () => {
        const dish = new NodeDish("42");

        expect(dish.toString()).toBe("42");
        expect(dish.valueOf()).toBe(42);
        expect(`${dish}`).toBe("42");
        expect(+dish).toBe(42);
        expect(new NodeDish(0).get("number")).toBe(0);
        expect(new NodeDish().get("string")).toBe("");
    });

    test("aliases to() to get()", () => {
        const dish = new NodeDish(Buffer.from("abc"));

        expect(dish.to("string")).toBe("abc");
        expect(dish.to(Dish.STRING)).toBe("abc");
    });

    test("uses presentation helpers for inspect output", () => {
        const dish = new NodeDish("inspect me");

        expect(dish.inspect()).toBe("inspect me");
        expect(dish[util.inspect.custom]()).toBe("inspect me");
        expect(util.inspect(dish)).toBe("inspect me");
    });

    test("applies a wrapped operation with optional arguments", () => {
        const standard = new NodeDish("hello?").apply(chef.toBase64);
        const urlSafe = new NodeDish("hello?").apply(
            chef.toBase64,
            ["A-Za-z0-9-_"],
        );

        expect(standard).toBeInstanceOf(NodeDish);
        expect(standard.value).toBe("aGVsbG8/");
        expect(urlSafe).toBeInstanceOf(NodeDish);
        expect(urlSafe.value).toBe("aGVsbG8");
    });
});
EOF
ls -l test/node"}

