import {spawn} from "node:child_process";
import path from "node:path";

function runRepl(commands) {
    return new Promise((resolve, reject) => {
        const child = spawn(process.execPath, ["--no-warnings", "src/node/repl.mjs"], {
            cwd: path.resolve(process.cwd()),
            stdio: ["pipe", "pipe", "pipe"],
        });

        let stdout = "";
        let stderr = "";
        const timeout = setTimeout(() => {
            child.kill("SIGKILL");
            reject(new Error(`REPL did not exit. stdout=${stdout} stderr=${stderr}`));
        }, 20000);

        child.stdout.on("data", (chunk) => {
            stdout += chunk;
        });
        child.stderr.on("data", (chunk) => {
            stderr += chunk;
        });
        child.on("error", (error) => {
            clearTimeout(timeout);
            reject(error);
        });
        child.on("close", (code) => {
            clearTimeout(timeout);
            resolve({code, stdout, stderr});
        });

        for (const command of commands) {
            child.stdin.write(`${command}\n`);
        }
        child.stdin.end();
    });
}

describe("node REPL", () => {
    test("starts with the Chef context and exports File globally", async () => {
        const {code, stdout, stderr} = await runRepl([
            "typeof File",
            "typeof bake",
            "toBase64('hi').toString()",
            ".exit",
        ]);

        expect(code).toBe(0);
        expect(stderr).not.toMatch(/Error/);
        expect(stdout).toContain("chef >");
        expect(stdout.match(/'function'/g)).toHaveLength(2);
        expect(stdout).toContain("'aGk='");
    }, 25000);
});
