export const eolSeqToCode = {
    "\u000a": "LF",
    "\u000b": "VT",
    "\u000c": "FF",
    "\u000d": "CR",
    "\u000d\u000a": "CRLF",
    "\u0085": "NEL",
    "\u2028": "LS",
    "\u2029": "PS"
