import "./jestEnv.mjs";
import {
    renderSpecialChar,
    escapeControlChars,
    eolSeqToCode,
    eolCodeToSeq,
    eolCodeToName
} from "../../../src/web/utils/editorUtils.mjs";

describe("editorUtils", () => {
    describe("renderSpecialChar", () => {
        test("renders the supplied placeholder and description on a cm-specialChar span", () => {
            const el = renderSpecialChar(0, "Control character null", "\u2400");

            expect(el.tagName).toBe("SPAN");
            expect(el.className).toBe("cm-specialChar");
            expect(el.textContent).toBe("\u2400");
            expect(el.title).toBe("Control character null");
            expect(el.getAttribute("aria-label")).toBe("Control character null");
        });

        test("rewrites the newline placeholder and description to line feed for code 0x0a", () => {
            const el = renderSpecialChar(0x0a, "Control character newline", "NL");

            expect(el.textContent).toBe("\u240a");
            expect(el.title).toBe("Control character line feed");
            expect(el.getAttribute("aria-label")).toBe("Control character line feed");
        });

        test("leaves non-newline descriptions untouched", () => {
            const el = renderSpecialChar(0x0d, "Control character carriage return", "CR");

            expect(el.textContent).toBe("CR");
            expect(el.title).toBe("Control character carriage return");
        });

        test.each([
            [0xe000, 0x00, "null"],
            [0xe009, 0x09, "0x9"],
            [0xe00a, 0x0a, "line feed"],
            [0xe00d, 0x0d, "carriage return"],
            [0xe01b, 0x1b, "escape"],
            [0xf8ff, 0x18ff, "0x18ff"]
        ])("maps private use area character %# to control picture U+%s", (code, rawCode, name) => {
            const el = renderSpecialChar(code, "ignored", "placeholder");

            expect(el.textContent).toBe(String.fromCharCode(0x2400 + rawCode));
            expect(el.title).toBe(`Control character ${name}`);
            expect(el.getAttribute("aria-label")).toBe(`Control character ${name}`);
        });

        test("does not remap private use characters outside the supported range", () => {
            const el = renderSpecialChar(0xf900, "Original description", "X");

            expect(el.textContent).toBe("X");
            expect(el.title).toBe("Original description");
        });
    });

    describe("escapeControlChars", () => {
        test("returns plain text unchanged", () => {
            expect(escapeControlChars("Hello, world!")).toBe("Hello, world!");
        });

        test("escapes whitespace to private use characters by default, then renders control pictures", () => {
            const result = escapeControlChars("\t");

            expect(result).toContain('class="cm-specialChar"');
            expect(result).toContain("\u2409");
            expect(result).toContain("Control character 0x9");
        });

        test("renders NUL and other low control characters as their control pictures when whitespace is preserved", () => {
            const nul = escapeControlChars("\u0000", true);
            const bell = escapeControlChars("\u0007", true);
            const escape = escapeControlChars("\u001b", true);

            expect(nul).toContain("\u2400");
            expect(nul).toContain("Control character null");
            expect(bell).toContain("\u2407");
            expect(bell).toContain("Control character bell");
            expect(escape).toContain("\u241b");
            expect(escape).toContain("Control character escape");
        });

        test("does not escape the line break sequence when whitespace is preserved", () => {
            expect(escapeControlChars("a\nb", true, "\n")).toBe("a\nb");
            expect(escapeControlChars("a\r\nb", true, "\r\n")).toBe("a\r\nb");
            expect(escapeControlChars("a\u2028b", true, "\u2028")).toBe("a\u2028b");
        });

        test("escapes characters that are not the configured line break", () => {
            const result = escapeControlChars("a\r\nb\u000bc", true, "\r\n");

            expect(result).toContain("a\r\nb");
            expect(result).toContain("\u240b");
            expect(result).toContain("Control character vertical tab");
            expect(result).not.toContain("\u000b");
            expect(result.endsWith("c")).toBe(true);
        });

        test("default escaping converts a line feed into a control picture rather than preserving it", () => {
            const result = escapeControlChars("a\nb");

            expect(result).toContain("a");
            expect(result).toContain("b");
            expect(result).toContain("\u240a");
            expect(result).toContain("Control character line feed");
            expect(result).not.toContain("\n");
        });

        test("uses a bullet placeholder for special characters above the control range", () => {
            const zeroWidth = escapeControlChars("\u200b", true);
            const del = escapeControlChars("\u007f", true);
            const softHyphen = escapeControlChars("\u00ad", true);

            expect(zeroWidth).toContain("\u2022");
            expect(zeroWidth).toContain("Control character zero width space");
            expect(del).toContain("\u2022");
            expect(del).toContain("Control character 0x7f");
            expect(softHyphen).toContain("\u2022");
            expect(softHyphen).toContain("Control character 0xad");
        });

        test("renders private use area characters as the control characters they represent", () => {
            const result = escapeControlChars("x\ue000y\ue009z", true);

            expect(result).toContain("\u2400");
            expect(result).toContain("Control character null");
            expect(result).toContain("\u2409");
            expect(result).toContain("Control character 0x9");
            expect(result).toContain("x");
            expect(result).toContain("y");
            expect(result).toContain("z");
        });

        test("handles several special characters in one string", () => {
            const result = escapeControlChars("\u0000\u0001\u0002", true);
            const count = (result.match(/class="cm-specialChar"/g) || []).length;

            expect(count).toBe(3);
            expect(result).toContain("Control character null");
            expect(result).toContain("Control character 0x1");
            expect(result).toContain("Control character 0x2");
        });

        test("does not HTML-escape ordinary markup characters", () => {
            expect(escapeControlChars("<b>&</b>", true)).toBe("<b>&</b>");
        });
    });

    describe("EOL lookup tables", () => {
        test("eolSeqToCode maps sequences to their codes", () => {
            expect(eolSeqToCode).toEqual({
                "\u000a": "LF",
                "\u000b": "VT",
                "\u000c": "FF",
                "\u000d": "CR",
                "\u000d\u000a": "CRLF",
                "\u0085": "NEL",
                "\u2028": "LS",
                "\u2029": "PS"
            });
        });

        test("eolCodeToSeq maps codes back to the matching sequences", () => {
            expect(eolCodeToSeq).toEqual({
                LF: "\u000a",
                VT: "\u000b",
                FF: "\u000c",
                CR: "\u000d",
                CRLF: "\u000d\u000a",
                NEL: "\u0085",
                LS: "\u2028",
                PS: "\u2029"
            });
        });

        test("EOL sequence and code tables round-trip", () => {
            for (const [seq, code] of Object.entries(eolSeqToCode)) {
                expect(eolCodeToSeq[code]).toBe(seq);
            }
        });

        test("eolCodeToName provides human readable names", () => {
            expect(eolCodeToName).toEqual({
                LF: "Line Feed",
                VT: "Vertical Tab",
                FF: "Form Feed",
                CR: "Carriage Return",
                CRLF: "Carriage Return + Line Feed",
                NEL: "Next Line",
                LS: "Line Separator",
                PS: "Paragraph Separator"
            });
        });
    });
});
