                "\u0085": "NEL",
                "\u2028": "LS",
                "\u2029": "PS"
            });
        });

        test("eolCodeToSeq maps codes back to the matching sequences", () => {
            expect(eolCodeToSeq).toEqual({
                LF: "\u000a",
                VT: "\u000b",
                FF: "\u000c",
                CR: "\u000d",
                CRLF: "\u000d\u000a",
                NEL: "\u0085",
                LS: "\u2028",
                PS: "\u2029"
