import "./jestEnv.mjs";
import {EditorState} from "@codemirror/state";
import {EditorView} from "@codemirror/view";
import {copyOverride, htmlCopyOverride} from "../../../src/web/utils/copyOverride.mjs";
import {createParent, resetDOM} from "./jestEnv.mjs";

let view;

function makeView(doc, selection) {
    const parent = createParent();
    view = new EditorView({
        state: EditorState.create({doc, selection}),
        parent
    });
    return view;
}

function makeClipboardEvent() {
    const clipboardData = {
        cleared: 0,
        data: [],
        clearData() {
            this.cleared++;
        },
        setData(type, value) {
            this.data.push([type, value]);
        }
    };
    const event = new window.Event("copy", {bubbles: true, cancelable: true});
    Object.defineProperty(event, "clipboardData", {value: clipboardData});
    return {event, clipboardData};
}

afterEach(() => {
    view?.destroy();
    view = undefined;
    resetDOM();
});

describe("htmlCopyOverride", () => {
    const originalGetSelection = window.getSelection;
    let selectedText = "";

    beforeEach(() => {
        selectedText = "";
        window.getSelection = () => ({toString: () => selectedText});
    });

    afterAll(() => {
        window.getSelection = originalGetSelection;
    });

    function makeEvent() {
        return {
            prevented: false,
            clipboardData: {
                cleared: 0,
                data: [],
                clearData() {
                    this.cleared++;
                },
                setData(type, value) {
                    this.data.push([type, value]);
                }
            },
            preventDefault() {
                this.prevented = true;
            }
        };
    }

    test("does nothing when there is no selection", () => {
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBeUndefined();
        expect(event.prevented).toBe(false);
        expect(event.clipboardData.cleared).toBe(0);
        expect(event.clipboardData.data).toEqual([]);
    });

    test("defers to the default handler when the selection contains no control pictures", () => {
        selectedText = "plain text";
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBe(false);
        expect(event.prevented).toBe(false);
        expect(event.clipboardData.data).toEqual([]);
    });

    test("converts control pictures back to their raw control characters", () => {
        selectedText = "a\u2400b\u2409c";
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBe(true);
        expect(event.prevented).toBe(true);
        expect(event.clipboardData.cleared).toBe(1);
        expect(event.clipboardData.data).toEqual([["text/plain", "a\u0000b\tc"]]);
    });

    test("handles the first and last characters of the control picture block", () => {
        selectedText = "\u2400\u243f";
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBe(true);
        expect(event.clipboardData.data).toEqual([["text/plain", "\u0000\u003f"]]);
    });

    test("does not consider characters just outside the control picture block", () => {
        selectedText = "\u23ff\u2440";
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBe(false);
        expect(event.clipboardData.data).toEqual([]);
    });

    test("only modifies control picture characters", () => {
        selectedText = "Start \u240a middle \u2028 end";
        const event = makeEvent();

        expect(htmlCopyOverride(event)).toBe(true);
        expect(event.clipboardData.data).toEqual([["text/plain", "Start \u000a middle \u2028 end"]]);
    });
});

describe("copyOverride", () => {
    test("returns a CodeMirror extension", () => {
        const ext = copyOverride();

        expect(ext).toBeDefined();
        expect(Array.isArray(ext) ? ext.length : 1).toBeGreaterThan(0);
    });

    test("copies selected private use area characters in their raw form", () => {
        const doc = "a\ue000b\ue009c";
        const editor = makeView(doc, {anchor: 0, head: doc.length});
        const {event, clipboardData} = makeClipboardEvent();

        editor.contentDOM.dispatchEvent(event);

        expect(event.defaultPrevented).toBe(true);
        expect(clipboardData.cleared).toBe(1);
        expect(clipboardData.data).toContainEqual(["text/plain", "a\u0000b\tc"]);
    });

    test("does not rewrite selections without private use area characters", () => {
        const doc = "plain selection";
        const editor = makeView(doc, {anchor: 0, head: doc.length});
        const {event, clipboardData} = makeClipboardEvent();

        editor.contentDOM.dispatchEvent(event);

        const copiedValues = clipboardData.data.map(([, value]) => value);
        expect(copiedValues).toContain("plain selection");
        expect(copiedValues).not.toContain("plain\u0000selection");
    });

    test("performs a line-wise copy when the selection is empty", () => {
        const doc = "first\ue001line\nsecond";
        const editor = makeView(doc, {anchor: 3, head: 3});
        const {event, clipboardData} = makeClipboardEvent();

        editor.contentDOM.dispatchEvent(event);

        expect(event.defaultPrevented).toBe(true);
        expect(clipboardData.data).toContainEqual(["text/plain", "first\u0001line"]);
    });

    test("only copies the selected range, not the whole line", () => {
        const doc = "xx\ue002yy";
        const editor = makeView(doc, {anchor: 2, head: 3});
        const {event, clipboardData} = makeClipboardEvent();

        editor.contentDOM.dispatchEvent(event);

        expect(event.defaultPrevented).toBe(true);
        expect(clipboardData.data).toContainEqual(["text/plain", "\u0002"]);
    });
});
