import "./jestEnv.mjs";
import {EditorState} from "@codemirror/state";
import {EditorView} from "@codemirror/view";
import {htmlPlugin} from "../../../src/web/utils/htmlWidget.mjs";
import {createParent, resetDOM} from "./jestEnv.mjs";

let view;

function makeView(html, {changed = false, lineSeparator} = {}) {
    const htmlOutput = {html, changed};
    const parent = createParent();
    view = new EditorView({
        state: EditorState.create({
            doc: "",
            ...(lineSeparator ? {lineSeparator} : {}),
            extensions: [htmlPlugin(htmlOutput)]
        }),
        parent
    });
    return {htmlOutput, widget: view.dom.querySelector("#output-html")};
}

afterEach(() => {
    view?.destroy();
    view = undefined;
    resetDOM();
});

describe("htmlPlugin", () => {
    test("does not create a widget when the HTML output is empty", () => {
        const {widget} = makeView("");

        expect(widget).toBeNull();
    });

    test("renders ordinary HTML inside a widget with the output-html id", () => {
        const {widget} = makeView("<p class='greeting'>Hello <strong>world</strong></p>");

        expect(widget).not.toBeNull();
        expect(widget.id).toBe("output-html");
        expect(widget.querySelector(".greeting").textContent).toBe("Hello world");
        expect(widget.querySelector("strong").textContent).toBe("world");
    });

    test("replaces control characters in text nodes with control pictures", () => {
        const {widget} = makeView("<p>a\u0000b</p>");

        const picture = widget.querySelector(".cm-specialChar");
        expect(picture).not.toBeNull();
        expect(picture.textContent).toBe("\u2400");
        expect(picture.title).toBe("Control character null");
        expect(widget.textContent).toBe("a\u2400b");
    });

    test("renders several control characters in different text nodes", () => {
        const {widget} = makeView("<p>\u0000</p><p>\u001b</p>");

        const pictures = widget.querySelectorAll(".cm-specialChar");
        expect(pictures).toHaveLength(2);
        expect(pictures[0].textContent).toBe("\u2400");
        expect(pictures[1].textContent).toBe("\u241b");
        expect(pictures[1].title).toBe("Control character escape");
    });

    test("renders HTML entities as literal text rather than markup", () => {
        const {widget} = makeView("<p>&lt;b&gt;not bold&lt;/b&gt;</p>");

        const p = widget.querySelector("p");
        expect(p.textContent).toBe("<b>not bold</b>");
        expect(p.querySelector("b")).toBeNull();
    });

    test("does not process control characters inside script or style elements", () => {
        const {widget} = makeView("<script>const x = '\u0000';</script><style>.a::after{content:'\u0001'}</style>");

        expect(widget.querySelector("script").textContent).toContain("\u0000");
        expect(widget.querySelector("style").textContent).toContain("\u0001");
        expect(widget.querySelector("script .cm-specialChar")).toBeNull();
        expect(widget.querySelector("style .cm-specialChar")).toBeNull();
    });

    test("preserves configured CRLF line breaks in text nodes", () => {
        const {widget} = makeView("a\r\nb", {lineSeparator: "\r\n"});

        expect(widget.textContent).toBe("a\r\nb");
        expect(widget.querySelector(".cm-specialChar")).toBeNull();
    });

    test("still renders control characters that are not part of the configured line break", () => {
        const {widget} = makeView("a\u000bb", {lineSeparator: "\r\n"});

        expect(widget.textContent).toBe("a\u240bb");
        expect(widget.querySelector(".cm-specialChar").title).toBe("Control character vertical tab");
    });

    test("attaches an HTML copy override to the widget", () => {
        const {widget} = makeView("<p>a\u2400b</p>");
        const originalGetSelection = window.getSelection;
        window.getSelection = () => ({toString: () => "a\u2400b"});
        const clipboardData = {
            cleared: 0,
            data: [],
            clearData() {
                this.cleared++;
            },
            setData(type, value) {
                this.data.push([type, value]);
            }
        };
        const event = new window.Event("copy", {bubbles: true, cancelable: true});
        Object.defineProperty(event, "clipboardData", {value: clipboardData});

        try {
            widget.dispatchEvent(event);
        } finally {
            window.getSelection = originalGetSelection;
        }

        expect(event.defaultPrevented).toBe(true);
        expect(clipboardData.cleared).toBe(1);
        expect(clipboardData.data).toEqual([["text/plain", "a\u0000b"]]);
    });

    test("re-decorates when the html output changes and resets the changed flag", () => {
        const {htmlOutput} = makeView("<p>one</p>");
        expect(view.dom.querySelector("#output-html").textContent).toBe("one");

        htmlOutput.html = "<p>two\u0000</p>";
        htmlOutput.changed = true;
        view.dispatch({selection: {anchor: 0}});

        const widget = view.dom.querySelector("#output-html");
        expect(widget.textContent).toBe("two\u2400");
        expect(widget.querySelector(".cm-specialChar")).not.toBeNull();
        expect(htmlOutput.changed).toBe(false);
    });

    test("keeps the current widget when the html output has not changed", () => {
        const {htmlOutput} = makeView("<p>one</p>");

        htmlOutput.html = "<p>two</p>";
        htmlOutput.changed = false;
        view.dispatch({selection: {anchor: 0}});

        expect(view.dom.querySelector("#output-html").textContent).toBe("one");
    });

    test("removes the widget when the output changes to an empty string", () => {
        const {htmlOutput} = makeView("<p>one</p>");

        htmlOutput.html = "";
        htmlOutput.changed = true;
        view.dispatch({selection: {anchor: 0}});

        expect(view.dom.querySelector("#output-html")).toBeNull();
        expect(htmlOutput.changed).toBe(false);
    });
});
