import {Compartment, EditorState} from "@codemirror/state";
import {EditorView} from "@codemirror/view";
import {panels, getPanel, showSidePanel} from "../../../src/web/utils/sidePanel.mjs";
import {createParent, resetDOM} from "./jestEnv.mjs";

let view;

function makePanelSpec({left = true, width = 100, withMount = true, withUpdate = true, withDestroy = true} = {}) {
    const calls = {mount: 0, update: 0, destroy: 0};
    const panel = {
        dom: document.createElement("div"),
        width,
        left
    };
    if (withMount) panel.mount = () => calls.mount++;
    if (withUpdate) panel.update = () => calls.update++;
    if (withDestroy) panel.destroy = () => calls.destroy++;
    return {panel, spec: () => panel, calls};
}

function makeView(extensions) {
    const parent = createParent();
    view = new EditorView({
        state: EditorState.create({doc: "abc", extensions}),
        parent
    });
    return view;
}

afterEach(() => {
    view?.destroy();
    view = undefined;
    resetDOM();
});

describe("panels", () => {
    test("returns an empty extension when no configuration is supplied", () => {
        expect(panels()).toEqual([]);
        expect(panels(null)).toEqual([]);
    });

    test("returns an extension when a configuration is supplied", () => {
        const extension = panels({});

        expect(Array.isArray(extension)).toBe(true);
        expect(extension).toHaveLength(1);
    });
});

describe("showSidePanel", () => {
    test("mounts a left panel and exposes it through getPanel", () => {
        const {panel, spec, calls} = makePanelSpec({left: true, width: 120});
        makeView([panels({}), showSidePanel.of(spec)]);

        const group = view.dom.querySelector(".cm-side-panels.cm-panels-left");
        expect(group).not.toBeNull();
        expect(group.contains(panel.dom)).toBe(true);
        expect(panel.dom.classList.contains("cm-panel")).toBe(true);
        expect(panel.dom.style.width).toBe("120px");
        expect(group.style.width).toBe("120px");
        expect(view.dom.querySelector(".cm-scroller").style.marginLeft).toBe("120px");
        expect(calls.mount).toBe(1);
        expect(getPanel(view, spec)).toBe(panel);
    });

    test("mounts a right panel and reserves space on the right", () => {
        const {panel, spec} = makePanelSpec({left: false, width: 75});
        makeView([panels({}), showSidePanel.of(spec)]);

        const group = view.dom.querySelector(".cm-side-panels.cm-panels-right");
        expect(group).not.toBeNull();
        expect(group.contains(panel.dom)).toBe(true);
        expect(view.dom.querySelector(".cm-side-panels.cm-panels-left")).toBeNull();
        expect(view.dom.querySelector(".cm-scroller").style.marginRight).toBe("75px");
        expect(view.dom.querySelector(".cm-scroller").style.marginLeft).toBe("");
    });

    test("lays out multiple panels in order and sums their widths", () => {
        const first = makePanelSpec({left: true, width: 30});
        const second = makePanelSpec({left: true, width: 55});
        makeView([panels({}), showSidePanel.of(first.spec), showSidePanel.of(second.spec)]);

        const group = view.dom.querySelector(".cm-side-panels.cm-panels-left");
        expect(group.style.width).toBe("85px");
        expect(Array.from(group.children)).toEqual([first.panel.dom, second.panel.dom]);
        expect(view.dom.querySelector(".cm-scroller").style.marginLeft).toBe("85px");
        expect(getPanel(view, first.spec)).toBe(first.panel);
        expect(getPanel(view, second.spec)).toBe(second.panel);
    });

    test("returns null for a panel constructor that is not active", () => {
        const active = makePanelSpec();
        const inactive = makePanelSpec();
        makeView([panels({}), showSidePanel.of(active.spec)]);

        expect(getPanel(view, active.spec)).toBe(active.panel);
        expect(getPanel(view, inactive.spec)).toBeNull();
    });

    test("ignores null panel constructors", () => {
        makeView([panels({}), showSidePanel.of(null)]);

        expect(view.dom.querySelector(".cm-side-panels")).toBeNull();
    });

    test("uses a supplied left container", () => {
        const leftContainer = document.createElement("div");
        const scroller = document.createElement("div");
        scroller.className = "cm-scroller";
        leftContainer.appendChild(scroller);
        document.body.appendChild(leftContainer);
        const {panel, spec} = makePanelSpec({left: true, width: 42});

        makeView([panels({leftContainer}), showSidePanel.of(spec)]);

        const group = leftContainer.querySelector(".cm-side-panels.cm-panels-left");
        expect(group).not.toBeNull();
        expect(group.contains(panel.dom)).toBe(true);
        expect(scroller.style.marginLeft).toBe("42px");
        expect(view.dom.querySelector(".cm-side-panels")).toBeNull();
    });

    test("calls update on active panels when the view updates", () => {
        const {spec, calls} = makePanelSpec();
        makeView([panels({}), showSidePanel.of(spec)]);

        view.dispatch({changes: {from: 0, insert: "x"}});

        expect(calls.update).toBeGreaterThan(0);
    });

    test("supports panels without an update method", () => {
        const {spec} = makePanelSpec({withUpdate: false});
        makeView([panels({}), showSidePanel.of(spec)]);

        expect(() => view.dispatch({selection: {anchor: 1}})).not.toThrow();
    });

    test("adds and removes a panel when the facet is reconfigured", () => {
        const compartment = new Compartment();
        const {panel, spec, calls} = makePanelSpec({left: true, width: 90});
        makeView([panels({}), compartment.of([])]);

        expect(getPanel(view, spec)).toBeNull();
        expect(view.dom.querySelector(".cm-side-panels")).toBeNull();

        view.dispatch({effects: compartment.reconfigure(showSidePanel.of(spec))});

        expect(calls.mount).toBe(1);
        expect(getPanel(view, spec)).toBe(panel);
        expect(view.dom.querySelector(".cm-side-panels").contains(panel.dom)).toBe(true);
        expect(view.dom.querySelector(".cm-scroller").style.marginLeft).toBe("90px");

        view.dispatch({effects: compartment.reconfigure([])});

        expect(calls.destroy).toBe(1);
        expect(getPanel(view, spec)).toBeNull();
        expect(view.dom.querySelector(".cm-side-panels")).toBeNull();
    });

    test("destroys panels when the view is destroyed", () => {
        const {spec, calls} = makePanelSpec();

        makeView([panels({}), showSidePanel.of(spec)]);
        view.destroy();
        view = undefined;

        expect(calls.destroy).toBe(1);
    });
});
