import "./jestEnv.mjs";
import {EditorState} from "@codemirror/state";
import {EditorView} from "@codemirror/view";
import {statusBar} from "../../../src/web/utils/statusBar.mjs";
import {createParent, resetDOM} from "./jestEnv.mjs";

let view;
let views;

function recorder(impl) {
    const calls = [];
    const fn = (...args) => {
        calls.push(args);
        return impl ? impl(...args) : undefined;
    };
    fn.calls = calls;
    return fn;
}

function makeOptions(overrides = {}) {
    return {
        label: "Input",
        timing: null,
        tabNumGetter: () => 0,
        eolHandler: recorder(),
        chrEncHandler: recorder(),
        chrEncGetter: () => 65001,
        getEncodingState: () => 2,
        getEOLState: () => 2,
        htmlOutput: {html: "", changed: false},
        ...overrides
    };
}

function makeView({doc = "hello", lineSeparator, opts = {}, extensions = []} = {}) {
    const options = makeOptions(opts);
    const parent = createParent();
    view = new EditorView({
        state: EditorState.create({
            doc,
            extensions: [
                ...(lineSeparator ? [EditorState.lineSeparator.of(lineSeparator)] : []),
                statusBar(options),
                ...extensions
            ]
        }),
        parent
    });
