        expect(button.getAttribute("data-original-title")).toBe("End of line sequence:<br>Line Feed");
    });

    test("shows CRLF when the state uses a CRLF line separator", () => {
        const {bar} = makeView({doc: "a\r\nb", lineSeparator: "\r\n"});

        expect(bar.querySelector(".eol-value").textContent).toBe("CRLF");
    });

    test("shows an unset EOL without the detected styling", () => {
        const {bar} = makeView({opts: {getEOLState: () => 0}});
        const value = bar.querySelector(".eol-value");

        expect(value.textContent).toBe("LF");
        expect(value.classList.contains("font-italic")).toBe(false);
        expect(value.classList.contains("pulse")).toBe(false);
    });

    test("marks a detected EOL sequence and removes the pulse after the timeout", () => {
        const originalSetTimeout = globalThis.setTimeout;
        const timers = [];
        globalThis.setTimeout = (callback, delay) => {
            timers.push({callback, delay});
            return timers.length;
        };
        let bar;
        try {
            ({bar} = makeView({opts: {getEOLState: () => 1}}));
        } finally {
            globalThis.setTimeout = originalSetTimeout;
        }

        const value = bar.querySelector(".eol-value");
        expect(value.textContent).toBe("LF (detected)");
        expect(value.classList.contains("font-italic")).toBe(true);
        expect(value.classList.contains("pulse")).toBe(true);

        const pulseTimer = timers.find(t => t.delay === 2000);
        expect(pulseTimer).toBeDefined();
        pulseTimer.callback();

        expect(value.classList.contains("pulse")).toBe(false);
        expect(value.classList.contains("font-italic")).toBe(true);
    });

    test("does not re-apply the detected styling while the EOL is unchanged", () => {
        const originalSetTimeout = globalThis.setTimeout;
        const timers = [];
        globalThis.setTimeout = (callback, delay) => {
            timers.push({callback, delay});
            return timers.length;
        };
        try {
            makeView({opts: {getEOLState: () => 1}});
            timers.find(t => t.delay === 2000).callback();
            view.dispatch({selection: {anchor: 1}});
        } finally {
            globalThis.setTimeout = originalSetTimeout;
        }

        // No additional 2 second timer should have been scheduled.
        expect(timers.filter(t => t.delay === 2000)).toHaveLength(1);
        expect(view.dom.querySelector(".eol-value").classList.contains("pulse")).toBe(false);
    });
});

