        const select = bar.querySelector(".chr-enc-select");
        const content = select.querySelector(".cm-status-bar-select-content");
        const filter = content.querySelector(".cm-status-bar-filter-input");

        click(select.querySelector(".cm-status-bar-select-btn"));
        click(filter);

        expect(content.classList.contains("show")).toBe(true);
    });

    test("calls the EOL handler and closes the drop-up when an EOL option is clicked", () => {
        const {bar, options} = makeView();
        const select = bar.querySelector(".eol-select");
        const content = select.querySelector(".cm-status-bar-select-content");
        const option = select.querySelector('a[data-val="CR"]');
        content.classList.add("show");

        const event = click(option);

        expect(event.defaultPrevented).toBe(true);
        expect(options.eolHandler.calls).toEqual([["CR", true]]);
        expect(content.classList.contains("show")).toBe(false);
    });

    test("ignores EOL clicks without a value", () => {
        const {bar, options} = makeView();
        const select = bar.querySelector(".eol-select");

        const event = click(select);

        expect(event.defaultPrevented).toBe(true);
        expect(options.eolHandler.calls).toEqual([]);
    });

    test("calls the encoding handler and updates the indicator when an encoding is clicked", () => {
        let encoding = 0;
        const chrEncHandler = recorder(val => {
            encoding = val;
        });
        const {bar, options} = makeView({
            opts: {chrEncGetter: () => encoding, chrEncHandler}
        });
        expect(bar.querySelector(".chr-enc-value").textContent).toBe("Raw Bytes");
        const select = bar.querySelector(".chr-enc-select");
        const content = select.querySelector(".cm-status-bar-select-content");
        content.classList.add("show");
        const option = select.querySelector('a[data-val="65001"]');

        const event = click(option);

        expect(event.defaultPrevented).toBe(true);
        expect(options.chrEncHandler.calls).toEqual([[65001, true]]);
        expect(bar.querySelector(".chr-enc-value").textContent).toBe("UTF-8 ");
        expect(content.classList.contains("show")).toBe(false);
    });

    test("ignores encoding clicks without a numeric value", () => {
        const {bar, options} = makeView();
        const select = bar.querySelector(".chr-enc-select");
        const content = select.querySelector(".cm-status-bar-select-content");
        const option = document.createElement("a");
        option.setAttribute("data-val", "not-a-number");
        content.appendChild(option);
        content.classList.add("show");

        const event = click(option);

        expect(event.defaultPrevented).toBe(true);
        expect(options.chrEncHandler.calls).toEqual([]);
        expect(content.classList.contains("show")).toBe(true);
    });

    test("filters the encoding list on keyup", () => {
        const {bar} = makeView();
        const content = bar.querySelector(".chr-enc-select .cm-status-bar-select-content");
        const input = content.querySelector(".cm-status-bar-filter-input");
        const rawBytes = content.querySelector('a[data-val="0"]');
        const utf8 = Array.from(content.querySelectorAll("a"))
            .find(a => a.textContent.trim() === "UTF-8");

        input.value = "utf";
        input.dispatchEvent(new window.KeyboardEvent("keyup", {bubbles: true}));

        expect(rawBytes.style.display).toBe("none");
        expect(utf8.style.display).toBe("block");

        input.value = "";
        input.dispatchEvent(new window.KeyboardEvent("keyup", {bubbles: true}));

        expect(rawBytes.style.display).toBe("block");
        expect(utf8.style.display).toBe("block");
    });
});
